vector<vector<int>> g;
vector<int> depth(3, 0);

void dfs(int u, int parent) {
    vector<int> nb = g[u];
    for (int v : nb) {
        if (v == parent) continue;
        depth[v] = depth[u] + 1;
        dfs(v, u);
    }
}

int main() {
    vector<int> a;
    a.push_back(1);
